pub(crate) fn tr_drop_from(block: &mut Block, words: &winnow_grammar::InternerContext, job: &TrJob) {
    match job {
        TrJob::Dropping { changed } => { tr_drop_in(block, words, changed); },
        _ => { },
    }
}

